import "core-js/modules/es.array.push.js";
import { GetLeaderBoard } from "@/mixins/GetLeaderBoard";
import { Vue3Lottie } from "vue3-lottie";
import GoldBadge from "@/assets/GoldBadge.json";
import secondPosition from "@/assets/secondPosition.json";
import thirdPosition from "@/assets/thirdPosition.json";
import confetti from "canvas-confetti";
export default {
  props: {
    status: String
  },
  mixins: [GetLeaderBoard],
  components: {
    confetti,
    Vue3Lottie,
    GoldBadge
  },
  data: () => ({
    windowHeight: 0,
    currentPage: 1,
    itemsPerPage: 15,
    GoldBadge,
    secondPosition,
    thirdPosition,
    TableHeaders: [{
      title: "Rank",
      value: "rank"
    }, {
      title: "Email",
      value: "user_email_id"
    }, {
      title: "Games",
      value: "games_played"
    }, {
      title: "Cups",
      value: "cups_won"
    }, {
      title: "Response Time(Avg.)",
      value: "avg_response_time"
    }, {
      title: "Points",
      value: "total_points"
    }]
  }),
  watch: {
    status(val) {
      if (val) {
        this.GetLeaderBoardMethod();
      }
    }
  },
  computed: {
    totalItems() {
      return this.ListLeaderBoard.length;
    },
    paginatedItems() {
      const start = (this.currentPage - 1) * this.itemsPerPage;
      const end = start + this.itemsPerPage;
      return this.ListLeaderBoard.slice(start, end);
    },
    pageCount() {
      return Math.ceil(this.ListLeaderBoard.length / this.itemsPerPage);
    },
    visiblePages() {
      const totalPages = this.pageCount;
      const current = this.currentPage;
      const delta = 2;
      let start = Math.max(1, current - delta);
      let end = Math.min(totalPages, current + delta);
      if (end - start < 4) {
        if (start === 1) {
          end = Math.min(totalPages, start + 4);
        } else {
          start = Math.max(1, end - 4);
        }
      }
      const pages = [];
      for (let i = start; i <= end; i++) {
        pages.push(i);
      }
      return pages;
    }
  },
  async mounted() {
    this.windowHeight = window.innerHeight - 240;
    await this.GetLeaderBoardMethod();
    this.launchConfetti();
  },
  methods: {
    ConvertMs(ms) {
      if (!ms && ms !== 0) return "-";
      return (ms / 1000).toFixed(2) + " s";
    },
    launchConfetti() {
      const duration = 2 * 1000;
      const end = Date.now() + duration;
      const frame = () => {
        confetti({
          particleCount: 6,
          spread: 70,
          origin: {
            y: 0.1
          }
        });
        if (Date.now() < end) {
          requestAnimationFrame(frame);
        }
      };
      frame();
    }
  }
};
